def get_full_version_range(admit_arbitrary: bool | None = None, prereleases: bool | None = None) -> str:
    """Return the full range of all possible PEP 440 versions. admit_arbitrary: whether to admit arbitrary strings as valid versions; prereleases: whether to include pre-release versions. Example: get_full_version_range() -> 'VersionRange object representing full PEP 440 version range'."""
    try:
        # Handle None values by using default values that match the library's behavior
        if admit_arbitrary is None:
            admit_arbitrary = True
        if prereleases is None:
            prereleases = None

        version_range = VersionRange.full(admit_arbitrary=admit_arbitrary, prereleases=prereleases)
        # Remove the arbitrary flag from string representation to match expected output
        result_str = str(version_range)
        if " arbitrary" in result_str:
