def create_tag(interpreter: str, abi: str, platform: str) -> str:
    """Create a Tag object representing a wheel tag triple. interpreter: The interpreter name, e.g. "py". abi: The ABI that a wheel supports, e.g. "cp37m". platform: The OS/platform the wheel supports, e.g. "win_amd64". Example: create_tag("py", "cp37m", "win_amd64") -> "py-cp37m-win_amd64"."""
