def generate_system_tags(warn: bool = False) -> list[str]:
    """Generate tags for the running interpreter. warn: whether warnings should be logged -> list of tag strings in format 'interpreter-abi-platform'"""
    try:
        tags = []
        for tag in sys_tags(warn=warn):
            tags.append(f"{tag.interpreter}-{tag.abi}-{tag.platform}")
        return tags
    except Exception as e:
        raise ValueError(f"Failed to generate system tags: {str(e)}")

