from packaging.tags import pure_python_tags
from typing import List


def generate_pure_python_tags(python_version: List[int] | None = None) -> List[str]:
    """Generate pure-Python tags compatible with the specified Python version. python_version: A one- or two-item sequence representing the compatible version of Python, e.g. [3, 9] -> ['cp39-none-any']. Defaults to current Python version."""
    try:
        # Convert the generator to a list and sort it properly
        tags = list(pure_python_tags(python_version))
        # Sort by the version part to match expected order
        def sort_key(tag_str):
            # Extract version part (e.g., "py39" -> 39, "py3" -> 3)
            version_part = tag_str.split('-')[0][2:]  # Remove "py" prefix
            if version_part == '3':
                return (0, 0)  # Special case for "py3"
            else:
                return (1, int(version_part))  # Other versions

        return sorted([str(tag) for tag in tags], key=sort_key)
    except Exception as e:
        raise ValueError(f"Failed to generate pure Python tags: {str(e)}")

