from typing import List, Optional


def generate_generic_tags(interpreter: Optional[str] = None, abis: Optional[List[str]] = None, platforms: Optional[List[str]] = None) -> List[dict]:
    """Generate generic tags for an interpreter requiring no specialization. interpreter: name of the interpreter, e.g. 'cp39'; abis: list of compatible ABIs, e.g. ['cp39', 'abi3']; platforms: list of compatible platforms, e.g. ['linux_x86_64'] -> [{"interpreter": "cp39", "abi": "cp39", "platform": "linux_x86_64"}]"""
    try:
        tags = list(generic_tags(interpreter=interpreter, abis=abis, platforms=platforms))
        result = []
        for tag in tags:
            result.append({
                "interpreter": tag.interpreter,
                "abi": tag.abi,
                "platform": tag.platform
            })
        return result
    except Exception as e:
        raise ValueError(f"Failed to generate generic tags: {str(e)}")

