from packaging.pylock import Pylock, PylockValidationError


def load_pylock_from_dict(data: Dict[str, Any]) -> Dict[str, Any]:
    """Create and validate a Pylock instance from a TOML dictionary. data: a TOML dictionary representing pylock data, e.g. {'package': 'requests', 'version': '2.28.1'} -> validated Pylock object"""
    try:
        pylock_instance = Pylock.from_dict(data)
        return {
            "packages": [
                {
                    "name": pkg.name,
                    "version": str(pkg.version),
                    "requires": list(pkg.requires) if pkg.requires else []
                }
                for pkg in pylock_instance.packages
            ]
        }
    except PylockValidationError as e:
        raise ValueError(f"Invalid pylock data: {str(e)}")
    except Exception as e:
        raise ValueError(f"Failed to create Pylock from data: {str(e)}")

from typing import Any, Dict
from packaging.pylock import Pylock
import dataclasses


def convert_pylock_to_dict(pylock_instance: Pylock) -> Dict[str, Any]:
    """Convert the Pylock instance to a TOML dictionary. pylock_instance: A validated Pylock instance to convert -> dict representation"""
    try:
        # Convert using dataclasses.asdict with a custom factory that handles Version objects
        def _toml_dict_factory(fields):
            result = {}
            for name, value in fields:
                # Convert Version objects to strings to ensure JSON compatibility
                if hasattr(value, '__class__') and value.__class__.__name__ == 'Version':
                    result[name] = str(value)
                else:
                    result[name] = value
            return result

        return dataclasses.asdict(pylock_instance, dict_factory=_toml_dict_factory)
    except Exception as e:
        raise ValueError(f"Failed to convert Pylock instance to dictionary: {str(e)}")
